import { mkdirSync, writeFileSync } from "fs";
import { resolve } from "path";
import { V21_SCHEMA_VERSION, type ChapterV21 } from "../types.js";

const outDirs = [
  resolve("state/chapters"),
  resolve("scripts/book/prompts/chapterflow-v21-authored/state/chapters"),
];
for (const outDir of outDirs) mkdirSync(outDir, { recursive: true });

type Q = ChapterV21["quiz"]["questions"][number];
type Ex = ChapterV21["examples"][number];

const bloom: Q["bloomsLevel"][] = [
  "understand", "apply", "analyze", "evaluate", "remember", "create", "apply", "analyze", "evaluate",
];

function question(bookId: string, n: number, i: number, prompt: string, choices: string[], correctIndex: number, explanation: string): Q {
  return {
    questionId: `${bookId}-ch${String(n).padStart(2, "0")}-q${String(i + 1).padStart(2, "0")}`,
    prompt,
    choices,
    correctIndex,
    explanation,
    bloomsLevel: bloom[i],
    depthLevel: i < 2 ? "standard" : i < 5 ? "deep" : "standard",
  };
}

function moveCorrectAnswers(chapter: ChapterV21, desired: number[]) {
  chapter.quiz.questions.forEach((q, i) => {
    const target = desired[i];
    const correct = q.choices[q.correctIndex];
    const distractors = q.choices.filter((_, idx) => idx !== q.correctIndex);
    const next = [...distractors];
    next.splice(target, 0, correct);
    q.choices = next;
    q.correctIndex = target;
  });
}

function example(bookId: string, n: number, i: number, title: string, tags: string[], domain: string, audience: string, stakes: string, format: string, scenario: string, whatToDo: string, whyItMatters: string): Ex {
  return {
    exampleId: `${bookId}-ch${String(n).padStart(2, "0")}-ex${String(i + 1).padStart(2, "0")}`,
    title,
    tags,
    planSpec: {
      domain,
      audience,
      stakes,
      format,
      requiredBeat: `Apply ${tags[1] ?? tags[0]} to ${stakes} without flattening the source case.`,
    },
    scenario,
    whatToDo,
    whyItMatters,
  };
}

